nodes.statement:
The best rate that can be achieved in the problem of Figure \ref{fig:SWzero} with $n = 1$ is the minimal entropy of the colorings of $G$, as shown in \cite{alon1996source}. This quantity is called \emph{chromatic entropy} and is denoted by 
\begin{align}
   H_{\chi}(G)\doteq \inf \lbrace H(c(V)) \:|\: c \text{ is a coloring of } G \rbrace.
\end{align}

The asymptotic optimal rate in the problem of Figure \ref{fig:SWzero} is characterized by
\begin{align}
        \overline{H}(G) = \lim_{n \rightarrow \infty} \frac{1}{n} H_{\chi}(G^{\wedge n}), \end{align}
where $G^{\wedge n}$ is the $n$-iterated \emph{AND product} of the characteristic graph $G$, see \cite{alon1996source}.

In order to complete the proof, we need Lemma \ref{lemma:partvalues}, it is the cornerstone of the connection between $\overline{H}(\sqcup \:\cdot\:)$ and $\overline{H}(\wedge \:\cdot\:)$. The main reasons why $\wedge$ appears in \eqref{eq:lemmapartvaluesA} are the AND powers used in $\overline{H}$, and the distributivity of $\wedge$ w.r.t. $\sqcup$ (see Lemma \ref{lemma:distrib}). The proof of Lemma \ref{lemma:partvalues} is developed in Section \ref{section:prooflemmapartvalues}.

\begin{lemma} Let $(\overline{a}_n)_{n \in \mathbb{N}^\star} \in \mathcal{A}^{\mathbb{N}^\star}$ be any sequence such that $T_{\overline{a}^n} \rightarrow P_A$ when $n \rightarrow \infty$. Then we have
    \begin{equation}
        \overline{H}\left(\bigsqcup_{a \in \mathcal{A}}^{P_A} G_a \right) = \lim_{n \rightarrow \infty} \frac{1}{n}H_\chi\left(\bigwedge_{a \in \mathcal{A}} G_a^{\wedge n T_{\overline{a}^n} (a)}\right). \end{equation}
\end{lemma}

Now let us prove Theorem \ref{th:partvalues}. Let $(\overline{a}_n)_{n \in \mathbb{N}^\star}$ be a $k$-periodic sequence such that $T_{\overline{a}^k} = P_A$, then $T_{\overline{a}^{nk}} = T_{\overline{a}^k}$ for all $n \in \mathbb{N}^\star$, and $T_{\overline{a}^n} \underset{n \rightarrow \infty}{\rightarrow} P_A$. We can use Lemma \ref{lemma:partvalues} and consider every $k$-th term in the limit:
\begin{align}
    \overline{H}\Big(\textstyle\bigsqcup_{a \in \mathcal{A}}^{P_A} G_a\Big) & = \lim\limits_{n \rightarrow \infty} \frac{1}{kn}H_\chi\Big(\textstyle\bigwedge_{a \in \mathcal{A}} G_a^{\wedge kn T_{\overline{a}^{kn}} (a)}\Big) \nonumber\\
    & = \lim\limits_{n \rightarrow \infty} \frac{1}{kn}H_\chi\Big(\Big(\textstyle\bigwedge_{a \in \mathcal{A}} G_a^{\wedge k T_{\overline{a}^{k}} (a)}\Big)^{\wedge n}\Big) \nonumber\\
    & = \frac{1}{k} \overline{H}\Big(\textstyle\bigwedge_{a \in \mathcal{A}} G_a^{\wedge k P_A (a)}\Big). &\vbox{\hrule height0.6pt\hbox{\vrule height1.3ex width0.6pt\hskip0.8ex\vrule width0.6pt}\hrule height0.6pt} \nonumber
\end{align}

In order to complete the proof, we need Lemma \ref{lemma:partvalues}, it is the cornerstone of the connection between $\overline{H}(\sqcup \:\cdot\:)$ and $\overline{H}(\wedge \:\cdot\:)$. The main reasons why $\wedge$ appears in \eqref{eq:lemmapartvaluesA} are the AND powers used in $\overline{H}$, and the distributivity of $\wedge$ w.r.t. $\sqcup$ (see Lemma \ref{lemma:distrib}). The proof of Lemma \ref{lemma:partvalues} is developed in Section \ref{section:prooflemmapartvalues}.

\begin{lemma} Let $(\overline{a}_n)_{n \in \mathbb{N}^\star} \in \mathcal{A}^{\mathbb{N}^\star}$ be any sequence such that $T_{\overline{a}^n} \rightarrow P_A$ when $n \rightarrow \infty$. Then we have
    \begin{equation}
        \overline{H}\left(\bigsqcup_{a \in \mathcal{A}}^{P_A} G_a \right) = \lim_{n \rightarrow \infty} \frac{1}{n}H_\chi\left(\bigwedge_{a \in \mathcal{A}} G_a^{\wedge n T_{\overline{a}^n} (a)}\right). \end{equation}
\end{lemma}

We can use Lemma \ref{lemma:partvalues} and consider every $k$-th term in the limit:
\begin{align}
    \overline{H}\Big(\textstyle\bigsqcup_{a \in \mathcal{A}}^{P_A} G_a\Big) & = \lim\limits_{n \rightarrow \infty} \frac{1}{kn}H_\chi\Big(\textstyle\bigwedge_{a \in \mathcal{A}} G_a^{\wedge kn T_{\overline{a}^{kn}} (a)}\Big) \nonumber\\
    & = \lim\limits_{n \rightarrow \infty} \frac{1}{kn}H_\chi\Big(\Big(\textstyle\bigwedge_{a \in \mathcal{A}} G_a^{\wedge k T_{\overline{a}^{k}} (a)}\Big)^{\wedge n}\Big) \nonumber\\
    & = \frac{1}{k} \overline{H}\Big(\textstyle\bigwedge_{a \in \mathcal{A}} G_a^{\wedge k P_A (a)}\Big). &\vbox{\hrule height0.6pt\hbox{\vrule height1.3ex width0.6pt\hskip0.8ex\vrule width0.6pt}\hrule height0.6pt} \nonumber
\end{align}

In this section, for all $i \in \mathbb{N}^\star$, $G_i$ denotes the cycle graph with $i$ vertices uniform distribution, i.e. $G_i = \big(C_i, \mathrm{Unif}(\lbrace 0, ..., i-1\rbrace)\big)$. Both $G_6$ and $G_8$ are perfect, and as shown in Figure \ref{fig:counterperfect}, $G_6 \wedge G_8$ is not a perfect graph. We have:
\begin{align}
    H_\kappa(G_6) & = H(V_6) - \max_{V_6 \in W_6 \in \Gamma(G_6)} H(V_6|W_6) \\
    & = 1 + \log 3 - \log 3 = 1
\end{align}
as $H(V_6|W_6)$ in
\eqref{eq:exampleA1} is maximized by taking $W_6 = \lbrace 0,2,4 \rbrace$ when $V_6 \in \lbrace 0,2,4 \rbrace$, and $W_6 = \lbrace 1,3,5 \rbrace$ otherwise.

Similarly, $H_\kappa(G_8) = 1$.

We can use Theorem \ref{th:Hbarperfect} to find $\overline{H}(G_6\wedge G_8)$:
\begin{align}
    \overline{H}(G_6\wedge G_8) = H_\kappa(G_6) + H_\kappa(G_8) = 2.
\end{align}

We can build an optimal coloring of $G_6 \wedge G_8$, $c^* : (v_6,v_8) \mapsto (\mathds{1}_{v_6 \text{ is even}}, \mathds{1}_{v_8 \text{ is even}})$.

For all $a \in \mathcal{A}$, let $G_a = (\mathcal{V}_a, \mathcal{E}_a, P_{V_A})$, and let $G = \bigsqcup^{P_A}_{a \in \mathcal{A}} G_a$. Let $P_A \in \Delta(\mathcal{A})$, and let $(\overline{a}_n)_{n \in \mathbb{N}^\star} \in \mathcal{A}^{\mathbb{N}^\star}$ be a sequence such that $T_{\overline{a}^n} \rightarrow P_A$ when $n \rightarrow \infty$.

Let $\epsilon > 0$, and for all $n \in \mathbb{N}^\star$ let 
\begin{align}
    & \mathcal{T}^n_\epsilon(P_A) \doteq \big\lbrace a^n \in \mathcal{A}^n \:\big|\: \| T_{a^n} - P_A \|_\infty \leq \epsilon \big\rbrace, \\
    & P'^n \doteq \frac{P^n_A}{P^n_A(\mathcal{T}^n_\epsilon(P_A))},\qquad \mathcal{S}_\epsilon^n \doteq \bigsqcup_{a^n \in \mathcal{T}^n_\epsilon(P_A)} \;\prod_{t \leq n} \mathcal{V}_{a_t}. \nonumber

\end{align}
By Lemma \ref{lemma:simplificationinduced} we have 
\begin{align}
      \overline{H}(G) = \lim_{n \rightarrow \infty} \frac{1}{n}H_\chi\Big(G^{\wedge n}[\mathcal{S}^n_\epsilon]\Big), \end{align}
as $P^n_V(\mathcal{S}^n_\epsilon) \rightarrow 1$ when $n \rightarrow \infty$. Let us study the limit in \eqref{eq:conclemmapart1}. For all $n$ large enough, $\overline{a}^n \in \mathcal{T}^n_\epsilon(P_A)$ as $T_{\overline{a}^n} \rightarrow P_A$. Therefore, for all $a^n \in \mathcal{T}^n_\epsilon(P_A)$ and $a' \in \mathcal{A}$,
\begin{align}
    \big|T_{\overline{a}^n}(a')-T_{a^n}(a')\big|\leq 2\epsilon. \end{align}

We have on one hand
\begin{align}
    & H_\chi\Big(\big(\textstyle\bigsqcup^{P_A}_{a \in \mathcal{A}} G_a\big)^{\wedge n}[\mathcal{S}^n_\epsilon]\Big) \nonumber\\
    =  \; & H_\chi\left(\left(\textstyle\bigsqcup_{a^n \in \mathcal{A}^n}^{P_A^n} \; \textstyle\bigwedge_{t \leq n} G_{a_t}\right)[\mathcal{S}^n_\epsilon]\right) \\
    = \; & H_\chi\left(\textstyle\bigsqcup_{a^n \in \mathcal{T}^n_\epsilon(P_A)}^{P'^n} \;\textstyle\bigwedge_{t \leq n} G_{a_t}\right) \\
    = \; & H_\chi\left(\textstyle\bigsqcup_{a^n \in \mathcal{T}^n_\epsilon(P_A)}^{P'^n} \; \textstyle\bigwedge_{a' \in \mathcal{A}} G_{a'}^{\wedge n T_{a^n}(a')}\right) \\
    \leq \; & H_\chi\left(\textstyle\bigsqcup_{a^n \in \mathcal{T}^n_\epsilon(P_A)}^{P'^n} \; \textstyle\bigwedge_{a' \in \mathcal{A}} G_{a'}^{\wedge n T_{\overline{a}^n}(a') + \lceil 2 n\epsilon \rceil}\right) \\
    = \; & H_\chi\left(\textstyle\bigwedge_{a' \in \mathcal{A}} G_{a'}^{\wedge n T_{\overline{a}^n}(a') + \lceil 2 n\epsilon \rceil}\right) \\
    \leq \; & H_\chi\left(\textstyle\bigwedge_{a' \in \mathcal{A}} G_{a'}^{\wedge n T_{\overline{a}^n}(a')}\right) + H_\chi\left(\textstyle\bigwedge_{a' \in \mathcal{A}} G_{a'}^{\wedge \lceil 2 n\epsilon\rceil}\right) \\
    \leq \; & H_\chi\left(\textstyle\bigwedge_{a' \in \mathcal{A}} G_{a'}^{\wedge n T_{\overline{a}^n}(a')}\right) + \lceil 2 n\epsilon \rceil|\mathcal{A}|\log|\mathcal{V}|; \end{align}
where \eqref{eq:lemmapartB1} comes from Lemma \ref{lemma:distrib}; \eqref{eq:lemmapartB2} comes from the definition of $\mathcal{S}_\epsilon^n$ and $P'^n$ in \eqref{eq:lemmapartA0}; \eqref{eq:lemmapartB3} is a rearrangement of the terms inside the product; \eqref{eq:lemmapartB4} comes from \eqref{eq:lemmapartB0}; \eqref{eq:lemmapartB5} follows from Lemma \ref{lemma:unionisomorph}, the graphs $\big(\bigwedge_{a' \in \mathcal{A}} G_{a'}^{\wedge n T_{\overline{a}^n}(a') + \lceil 2 n\epsilon \rceil}\big)_{a^n \in \mathcal{T}^n_\epsilon(P_A)}$ are isomorphic as they do not depend on $a^n$; \eqref{eq:lemmapartB5a} follows from the subadditivity of $H_\chi$; and \eqref{eq:lemmapartB6} is the upper bound on $H_\chi$ given by the highest entropy of a coloring.

On the other hand, we obtain with similar arguments
\begin{align}
    & H_\chi\Big(\big(\textstyle\bigsqcup^{P_A}_{a \in \mathcal{A}} G_a\big)^{\wedge n}[\mathcal{S}^n_\epsilon]\Big) \nonumber\\
    \geq \: & H_\chi\left(\textstyle\bigwedge_{a' \in \mathcal{A}} G_{a'}^{\wedge n T_{\overline{a}^n}(a') - \lceil 2 n\epsilon \rceil}\right) \\
    \geq \: & H_\chi\left(\textstyle\bigwedge_{a' \in \mathcal{A}} G_{a'}^{\wedge n T_{\overline{a}^n}(a')}\right) - H_\chi\left(\textstyle\bigwedge_{a' \in \mathcal{A}} G_{a'}^{\wedge \lceil 2 n\epsilon\rceil}\right), \\
    \geq \: & H_\chi\left(\textstyle\bigwedge_{a' \in \mathcal{A}} G_{a'}^{\wedge n T_{\overline{a}^n}(a')}\right) - \lceil 2 n\epsilon \rceil|\mathcal{A}|\log|\mathcal{V}|. \end{align}
Note that \eqref{eq:lemmapartC4a} also comes from the subadditivity of $H_\chi$ : $H_\chi(G_2) \geq H_\chi(G_1 \wedge G_2) - H_\chi(G_1)$ for all $G_1, G_2$.

By combining \eqref{eq:lemmapartB6} and \eqref{eq:lemmapartC5} we obtain
\begin{align}
    & \left|\lim_{n \rightarrow \infty} \frac{1}{n} H_\chi(G^{\wedge n}[\mathcal{S}^n_\epsilon]) - \lim_{n \rightarrow \infty} \frac{1}{n} H_\chi\left(\bigwedge_{a' \in \mathcal{A}} G_{a'}^{\wedge n T_{\overline{a}^n}(a')}\right)\right| \nonumber \\
    & \leq 2\epsilon|\mathcal{A}|\log|\mathcal{V}|. \end{align}

As this holds for all $\epsilon > 0$, combining \eqref{eq:conclemmapart1} and \eqref{eq:conclemmapart2} yields the desired result.

Let $\epsilon > 0$, and for all $n \in \mathbb{N}^\star$ let 
\begin{align}
    & \mathcal{T}^n_\epsilon(P_A) \doteq \big\lbrace a^n \in \mathcal{A}^n \:\big|\: \| T_{a^n} - P_A \|_\infty \leq \epsilon \big\rbrace, \\
    & P'^n \doteq \frac{P^n_A}{P^n_A(\mathcal{T}^n_\epsilon(P_A))},\qquad \mathcal{S}_\epsilon^n \doteq \bigsqcup_{a^n \in \mathcal{T}^n_\epsilon(P_A)} \;\prod_{t \leq n} \mathcal{V}_{a_t}. \nonumber

\end{align}

By Lemma \ref{lemma:simplificationinduced} we have 
\begin{align}
      \overline{H}(G) = \lim_{n \rightarrow \infty} \frac{1}{n}H_\chi\Big(G^{\wedge n}[\mathcal{S}^n_\epsilon]\Big), \end{align}
as $P^n_V(\mathcal{S}^n_\epsilon) \rightarrow 1$ when $n \rightarrow \infty$.

Let us study the limit in \eqref{eq:conclemmapart1}. For all $n$ large enough, $\overline{a}^n \in \mathcal{T}^n_\epsilon(P_A)$ as $T_{\overline{a}^n} \rightarrow P_A$. Therefore, for all $a^n \in \mathcal{T}^n_\epsilon(P_A)$ and $a' \in \mathcal{A}$,
\begin{align}
    \big|T_{\overline{a}^n}(a')-T_{a^n}(a')\big|\leq 2\epsilon. \end{align}

By combining \eqref{eq:lemmapartB6} and \eqref{eq:lemmapartC5} we obtain
\begin{align}
    & \left|\lim_{n \rightarrow \infty} \frac{1}{n} H_\chi(G^{\wedge n}[\mathcal{S}^n_\epsilon]) - \lim_{n \rightarrow \infty} \frac{1}{n} H_\chi\left(\bigwedge_{a' \in \mathcal{A}} G_{a'}^{\wedge n T_{\overline{a}^n}(a')}\right)\right| \nonumber \\
    & \leq 2\epsilon|\mathcal{A}|\log|\mathcal{V}|. \end{align}

$(\Longrightarrow)$ Assume that $\overline{H}\left(\textstyle\bigwedge_{a \in \mathcal{A}} G_{a}\right) = \textstyle\sum_{a \in \mathcal{A}} \overline{H}(G_{a})$.

We can use Corollary \ref{cor:unif}: $\overline{H}\big(\bigsqcup_{a \in \mathcal{A}}^{\mathrm{Unif}(\mathcal{A})} G_a\big) = \sum_{a \in \mathcal{A}} \frac{1}{|\mathcal{A}|}\overline{H}(G_{a})$. Thus, the function $P_A \mapsto \overline{H}\big(\bigsqcup_{a \in \mathcal{A}}^{P_A} G_a\big)$ is convex by Lemma \ref{th:etaconvex}, and satisfies \eqref{eq:lemma1A} with the interior point $P_A = \mathrm{Unif}(\mathcal{A})$: by Lemma \ref{lemma:convexanalysis} we have
\begin{align}
    \forall P_A \in \Delta(\mathcal{A}),\; \overline{H}\big(\textstyle\bigsqcup_{a \in \mathcal{A}}^{P_A} G_a\big) = \textstyle\sum_{a \in \mathcal{A}} P_A(a) \overline{H}(G_a). \end{align}

$(\Longleftarrow)$ Conversely, assume \eqref{eq:proofcormainB}, then $P_A \mapsto \overline{H}\big(\bigsqcup_{a \in \mathcal{A}}^{P_A} G_a\big)$ is linear. We can use Corollary \ref{cor:unif}, and we have $\overline{H}\big( \bigwedge_{a \in \mathcal{A}} G_a \big) = |\mathcal{A}|\overline{H}\big(\bigsqcup_{a \in \mathcal{A}}^{\mathrm{Unif}(\mathcal{A})} G_a\big) = \sum_{a \in \mathcal{A}} \overline{H}(G_{a})$.

$(\Longrightarrow)$ Assume that $\overline{H}\left(\textstyle\bigwedge_{a \in \mathcal{A}} G_{a}\right) = \textstyle\sum_{a \in \mathcal{A}} \overline{H}(G_{a})$.

We can use Corollary \ref{cor:unif}: $\overline{H}\big(\bigsqcup_{a \in \mathcal{A}}^{\mathrm{Unif}(\mathcal{A})} G_a\big) = \sum_{a \in \mathcal{A}} \frac{1}{|\mathcal{A}|}\overline{H}(G_{a})$. Thus, the function $P_A \mapsto \overline{H}\big(\bigsqcup_{a \in \mathcal{A}}^{P_A} G_a\big)$ is convex by Lemma \ref{th:etaconvex}, and satisfies \eqref{eq:lemma1A} with the interior point $P_A = \mathrm{Unif}(\mathcal{A})$: by Lemma \ref{lemma:convexanalysis} we have
\begin{align}
    \forall P_A \in \Delta(\mathcal{A}),\; \overline{H}\big(\textstyle\bigsqcup_{a \in \mathcal{A}}^{P_A} G_a\big) = \textstyle\sum_{a \in \mathcal{A}} P_A(a) \overline{H}(G_a). \end{align}

By \cite[Lemma 3]{tuncel2009complementary}, if $G$ is perfect then 
\begin{align}
    \overline{H}(G \overset{(\alpha, 1-\alpha)}{\sqcup} G_5) = \alpha \overline{H}(G) + (1-\alpha)\overline{H}(G_5).
\end{align}
By Theorem \ref{th:caraclin}, we have $\overline{H}(G \wedge G_5) = \overline{H}(G) + \overline{H}(G_5) = H_\kappa(G) + \frac{\log 5}{2}$; where the last equality comes from \cite[Example 1]{koulgi2003zero} which states that $\overline{H}(G_5) = \frac{\log 5}{2}$, and from Theorem \ref{th:mainperfect}.

The probabilistic graphs in both sides of \eqref{eq:distribunion} have 
    \begin{align}
        \left(\bigsqcup_{a \in \mathcal{A}} \mathcal{V}_a\right) \times \left(\bigsqcup_{b \in \mathcal{B}} \mathcal{V}_b\right) = \bigsqcup_{(a,b) \in \mathcal{A}\times \mathcal{B}} \mathcal{V}_a \times \mathcal{V}_b
    \end{align}
    as set of vertices, with underlying distribution 
    \begin{align}
        & \left(\sum_{a \in \mathcal{A}} P_A(a) P_{V_a}\right)\left(\sum_{b \in \mathcal{B}} P_B(b) P_{V_b}\right) \nonumber\\
        & = \sum_{(a,b) \in \mathcal{A}\times \mathcal{B}} P_A(a) P_B(b) P_{V_a} P_{V_b}.
    \end{align}

    Now let us show that these two graphs have the same edges. Let $(v_{\mathcal{A}},v_{\mathcal{B}}),(v'_{\mathcal{A}},v'_{\mathcal{B}}) \in \left(\bigsqcup_{a \in \mathcal{A}} \mathcal{V}_a\right) \times \left(\bigsqcup_{b \in \mathcal{B}} \mathcal{V}_b\right)$; let $a_*, a'_* \in \mathcal{A}$ and $b_*,b'_* \in \mathcal{B}$ be the unique indexes such that
    \begin{align}
        (v_{\mathcal{A}},v_{\mathcal{B}}) \in \mathcal{V}_{a_*} \times \mathcal{V}_{b_*} \quad \text{and} \quad (v'_{\mathcal{A}},v'_{\mathcal{B}}) \in \mathcal{V}_{a'_*} \times \mathcal{V}_{b'_*}.
    \end{align}
    We have:
    \begin{align}
        &  \!\!\! (v_{\mathcal{A}},v_{\mathcal{B}}),(v'_{\mathcal{A}},v'_{\mathcal{B}}) \text{ are adjacent in } \left(\bigsqcup_{a \in \mathcal{A}}^{P_A} G_a\right) \wedge \left(\bigsqcup_{b \in \mathcal{B}}^{P_B} G_b\right)\\
        \Longleftrightarrow & \; v_{\mathcal{A}}, v'_{\mathcal{A}} \text{ adjacent in } \bigsqcup_{a \in \mathcal{A}}^{P_A} G_a \text{ and } \nonumber\\
        & v_{\mathcal{B}}, v'_{\mathcal{B}} \text{ adjacent in } \bigsqcup_{b \in \mathcal{B}}^{P_B} G_b\\
        \Longleftrightarrow & \; a_* = a'_* \text{ and } v_{\mathcal{A}} v'_{\mathcal{A}} \in \mathcal{E}_{a_*} \text{ and } b_* = b'_* \text{ and } v_{\mathcal{B}} v'_{\mathcal{B}} \in \mathcal{E}_{b_*} \\
        \Longleftrightarrow & \; (a_*,b_*) = (a'_*, b'_*) \text{ and } \nonumber\\ 
        & \; (v_{\mathcal{A}},v_{\mathcal{B}}),(v'_{\mathcal{A}},v'_{\mathcal{B}}) \text{ are adjacent in } G_{a_*} \wedge G_{b_*} \\
        \Longleftrightarrow & \; (v_{\mathcal{A}},v_{\mathcal{B}}),(v'_{\mathcal{A}},v'_{\mathcal{B}}) \text{ are adjacent in } \bigsqcup_{(a,b) \in \mathcal{A} \times \mathcal{B}}^{P_AP_B} G_a \wedge G_b.
    \end{align}

The probabilistic graphs in both sides of \eqref{eq:distribunion} have 
    \begin{align}
        \left(\bigsqcup_{a \in \mathcal{A}} \mathcal{V}_a\right) \times \left(\bigsqcup_{b \in \mathcal{B}} \mathcal{V}_b\right) = \bigsqcup_{(a,b) \in \mathcal{A}\times \mathcal{B}} \mathcal{V}_a \times \mathcal{V}_b
    \end{align}
    as set of vertices, with underlying distribution 
    \begin{align}
        & \left(\sum_{a \in \mathcal{A}} P_A(a) P_{V_a}\right)\left(\sum_{b \in \mathcal{B}} P_B(b) P_{V_b}\right) \nonumber\\
        & = \sum_{(a,b) \in \mathcal{A}\times \mathcal{B}} P_A(a) P_B(b) P_{V_a} P_{V_b}.
    \end{align}

Let $(v_{\mathcal{A}},v_{\mathcal{B}}),(v'_{\mathcal{A}},v'_{\mathcal{B}}) \in \left(\bigsqcup_{a \in \mathcal{A}} \mathcal{V}_a\right) \times \left(\bigsqcup_{b \in \mathcal{B}} \mathcal{V}_b\right)$; let $a_*, a'_* \in \mathcal{A}$ and $b_*,b'_* \in \mathcal{B}$ be the unique indexes such that
    \begin{align}
        (v_{\mathcal{A}},v_{\mathcal{B}}) \in \mathcal{V}_{a_*} \times \mathcal{V}_{b_*} \quad \text{and} \quad (v'_{\mathcal{A}},v'_{\mathcal{B}}) \in \mathcal{V}_{a'_*} \times \mathcal{V}_{b'_*}.
    \end{align}

By Lemma \ref{lemma:induced}, we have for all $n \in \mathbb{N}^\star$:
\begin{align}
    & H_\chi(G^{\wedge n}) - 1 - (1-P^n_V(\mathcal{S}^n))\log|\mathcal{V}| \nonumber\\
    \leq \: & H_\chi(G^{\wedge n}[\mathcal{S}^n]) \leq \frac{H_\chi(G^{\wedge n})}{P^n_V(\mathcal{S}^n)}.
\end{align}
Since $P^n_V(\mathcal{S}^n) \rightarrow 1$, and $H_\chi(G^{\wedge n}) = n \overline{H}(G) + o(n)$ when $n \rightarrow \infty$, the desired results follows immediately by normalization and limit.

\textbf{($\eta$ Lipschitz)} Let us first prove that $\eta$ is Lipschitz. For all $P_A, P'_A \in \Delta(\mathcal{A})$ we need to bound the quantity $|\eta(P_A)-\eta(P'_A)|$; by Lemma \ref{lemma:partvalues} this is equivalent to bounding
\begin{align}
     \lim_{n \rightarrow \infty} \frac{1}{n}\left|H_\chi\left(\bigwedge_{a \in \mathcal{A}} G_a^{\wedge n T_{\overline{a}^n} (a)}\right) - H_\chi\left(\bigwedge_{a \in \mathcal{A}} G_a^{\wedge n T_{\overline{a}'^n} (a)}\right)\right| \end{align}
where $(T_{\overline{a}^n}, T_{\overline{a}'^n}) \rightarrow (P_A, P'_A)$ when $n \rightarrow \infty$.

Fix $n \in \mathbb{N}^\star$, we assume that the quantity inside $|\cdot|$ in \eqref{eq:prooflemmaetaconvexA0} is positive; the other case can be treated with the same arguments by symmetry of the roles. We have
\begin{align}
    & H_\chi\left(\bigwedge_{a \in \mathcal{A}} G_a^{\wedge n T_{\overline{a}^n} (a)}\right) - H_\chi\left(\bigwedge_{a \in \mathcal{A}} G_a^{\wedge n T_{\overline{a}'^n} (a)}\right) \\
    \leq & \; H_\chi\left(\bigwedge_{a \in \mathcal{A}} G_a^{\wedge n T_{\overline{a}^n} (a)}\right) - H_\chi\Bigg(\bigwedge_{a \in \mathcal{A}} G_a^{\wedge n \min(T_{\overline{a}^n}(a),T_{\overline{a}'^n}(a))}\! \Bigg) \\
    = & \; H_\chi\Bigg(\!\bigwedge_{a \in \mathcal{A}} G_a^{\wedge n \min(T_{\overline{a}^n}(a),T_{\overline{a}'^n}(a))} \bigwedge_{a \in \mathcal{A}} G_a^{\wedge n |T_{\overline{a}^n}(a)-T_{\overline{a}'^n}(a)|_+}\!\!\Bigg) \nonumber\\
    & - H_\chi\Bigg(\bigwedge_{a \in \mathcal{A}} G_a^{\wedge n \min(T_{\overline{a}^n}(a),T_{\overline{a}'^n}(a))} \Bigg) \\
    \leq & \; H_\chi\Bigg(\bigwedge_{a \in \mathcal{A}} G_a^{\wedge n |T_{\overline{a}^n}(a)-T_{\overline{a}'^n}(a)|_+}\Bigg) \\
    \leq & \; \log\left(\max_a |\mathcal{V}_a|\right) \sum_{a \in \mathcal{A}} n |T_{\overline{a}^n}(a)-T_{\overline{a}'^n}(a)|_+ \\
    \leq & \; n \log\left(\max_a |\mathcal{V}_a|\right) \|T_{\overline{a}^n}-T_{\overline{a}'^n}\|_1, \end{align}
