    P_{W^*}(\mathcal{S}) > 0 \Longrightarrow \forall a \in \mathcal{A}, \, P_{W^*_a}(\mathcal{S}_a) > 0.
\end{align}
The conditional distribution w.r.t. $(A = a)$ writes:
\begin{align}
    P_{W^*| A = a}(\mathcal{S}) = & \sum_{v_a \in \mathcal{V}_a} P_{V_a}(v_a) P_{W^*| A = a, V = v_a}(\mathcal{S}) \\
    = & \sum_{v_a \in \mathcal{V}_a} P_{V_a}(v_a) P_{W^*_a|V_a = v_a}(\mathcal{S}_a) \prod_{\substack{a' \in \mathcal{A} \\ a' \neq a}} P_{W^*_{a'}}(\mathcal{S}_{a'}) \\
    = & \prod_{a' \in \mathcal{A}} P_{W^*_{a'}}(\mathcal{S}_{a'}). \end{align}
It follows that the random variable $W^*$ is independent of $A$ as the expression \eqref{eq:proofHkappasplitW4} does not depend on $a$. Note that $P_{W^*}$ defined in \eqref{eq:defWstar} is a probability distribution, as 
\begin{align}
    \sum_{\mathcal{S} \in \Gamma(G)} P_{W^*}(\mathcal{S}) = & \; \sum_{\mathcal{S} \in \Gamma(G)} \;\;\prod_{a' \in \mathcal{A}} P_{W^*_{a'}}(\mathcal{S}_{a'}) \\
    = & \; \sum_{(\mathcal{S}_{a'})_{a' \in \mathcal{A}} \in \prod_{a' \in \mathcal{A}} \Gamma(G_{a'})} \;\; \prod_{a' \in \mathcal{A}}P_{W^*_{a'}}(\mathcal{S}_{a'}) \\
    = & \; 1, \end{align}
where \eqref{eq:proofHkappasplitX2} comes from \eqref{eq:proofHkappasplitW4}; \eqref{eq:proofHkappasplitX3} follows from $\Gamma(G) = \big\lbrace \bigsqcup_{a \in \mathcal{A}} \mathcal{S}_a \:\big|\: \forall a \in \mathcal{A}, \, \mathcal{S}_a \in \Gamma(G_a) \big\rbrace$; and \eqref{eq:proofHkappasplitX4} holds as $W^*_a$ takes its values in $\Gamma(G_a)$ for all $a \in \mathcal{A}$.

Now, let us show that $V \in W^*$ with probability one. For all $a \in \mathcal{A}$ and $v_a \in \mathcal{V}_a$,
\begin{align}
    \lbrace \mathcal{S} \cap \mathcal{V}_a \:|\: \mathcal{S} \in \mathrm{supp} P_{W^*|V = v_a} \rbrace = \mathrm{supp} P_{W^*_a|V_a = v_a};
\end{align}
where $\mathrm{supp}$ denotes the support of a probability distribution. Since $V_a \in W^*_a$ with probability one, all the sets in $\mathrm{supp} P_{W^*_a|V_a = v_a}$ contain $v_a$, hence all sets in $\mathrm{supp} P_{W^*|V = v_a}$ also contain $v_a$: $V \in W^*$ with probability one.

Now let us combine the results on $W^*$:
\begin{align}
    H_\kappa(G) & \leq I(V;W^*) \\
    & = I(V,A;W^*) \\
    & = I(A;W^*) + \sum_{a \in \mathcal{A}} P_A(a) I(V;W^*|A = a) \\
    & = \sum_{a \in \mathcal{A}} P_A(a) I(V_a;W_a^*) \\
    & = \sum_{a \in \mathcal{A}} P_A(a) H_\kappa(G_a); \end{align}
where \eqref{eq:proofHkappasplitZ1} holds as $W^*$ takes its values in $\Gamma(G)$ and $V \in W^*$ with probability one; \eqref{eq:proofHkappasplitZ2} holds as $A$ is a deterministic function of $V$; \eqref{eq:proofHkappasplitZ3} comes from the decomposition $I(V,A;W) = I(V;W|A) + I(A;W)$; \eqref{eq:proofHkappasplitZ4} follows from the independence of $A$ and $W^*$; \eqref{eq:proofHkappasplitZ5} comes from the fact that $W^*_a$ minimizes \eqref{eq:defWastar}. \newline

\textit{Achievability}

For all $a \in \mathcal{A}$, let $W^*_a$ be a minimizer of
\begin{align}
    \min_{V_a \in W_a \in \Gamma(G_a)} I(V_a;W_a). \end{align}

Let $W^*$ be the random variable defined as follows: for all $\mathcal{S} \in \Gamma(G)$, $a \in \mathcal{A}$ and $v_a \in \mathcal{V}_a$,
\begin{align}
    P_{W^*| A = a, V = v_a}(\mathcal{S}) \doteq P_{W^*_a|V_a = v_a}(\mathcal{S}_a) \prod_{\substack{a' \in \mathcal{A} \\ a' \neq a}} P_{W^*_{a'}}(\mathcal{S}_{a'}), \end{align}
where $\mathcal{S}$ is uniquely decomposed as $\bigsqcup_{a \in \mathcal{A}} \mathcal{S}_a$, with $\mathcal{S}_a \in \Gamma(G_a)$ for all $a \in \mathcal{A}$.

The random variable $W^*$ takes its values in $\Gamma(G)$, as
\begin{align}
    P_{W^*}(\mathcal{S}) > 0 \Longrightarrow \forall a \in \mathcal{A}, \, P_{W^*_a}(\mathcal{S}_a) > 0.
\end{align}

The conditional distribution w.r.t. $(A = a)$ writes:
\begin{align}
    P_{W^*| A = a}(\mathcal{S}) = & \sum_{v_a \in \mathcal{V}_a} P_{V_a}(v_a) P_{W^*| A = a, V = v_a}(\mathcal{S}) \\
    = & \sum_{v_a \in \mathcal{V}_a} P_{V_a}(v_a) P_{W^*_a|V_a = v_a}(\mathcal{S}_a) \prod_{\substack{a' \in \mathcal{A} \\ a' \neq a}} P_{W^*_{a'}}(\mathcal{S}_{a'}) \\
    = & \prod_{a' \in \mathcal{A}} P_{W^*_{a'}}(\mathcal{S}_{a'}). \end{align}
It follows that the random variable $W^*$ is independent of $A$ as the expression \eqref{eq:proofHkappasplitW4} does not depend on $a$.

Note that $P_{W^*}$ defined in \eqref{eq:defWstar} is a probability distribution, as 
\begin{align}
    \sum_{\mathcal{S} \in \Gamma(G)} P_{W^*}(\mathcal{S}) = & \; \sum_{\mathcal{S} \in \Gamma(G)} \;\;\prod_{a' \in \mathcal{A}} P_{W^*_{a'}}(\mathcal{S}_{a'}) \\
    = & \; \sum_{(\mathcal{S}_{a'})_{a' \in \mathcal{A}} \in \prod_{a' \in \mathcal{A}} \Gamma(G_{a'})} \;\; \prod_{a' \in \mathcal{A}}P_{W^*_{a'}}(\mathcal{S}_{a'}) \\
    = & \; 1, \end{align}
where \eqref{eq:proofHkappasplitX2} comes from \eqref{eq:proofHkappasplitW4}; \eqref{eq:proofHkappasplitX3} follows from $\Gamma(G) = \big\lbrace \bigsqcup_{a \in \mathcal{A}} \mathcal{S}_a \:\big|\: \forall a \in \mathcal{A}, \, \mathcal{S}_a \in \Gamma(G_a) \big\rbrace$; and \eqref{eq:proofHkappasplitX4} holds as $W^*_a$ takes its values in $\Gamma(G_a)$ for all $a \in \mathcal{A}$.

Now, let us show that $V \in W^*$ with probability one. For all $a \in \mathcal{A}$ and $v_a \in \mathcal{V}_a$,
\begin{align}
    \lbrace \mathcal{S} \cap \mathcal{V}_a \:|\: \mathcal{S} \in \mathrm{supp} P_{W^*|V = v_a} \rbrace = \mathrm{supp} P_{W^*_a|V_a = v_a};
\end{align}
where $\mathrm{supp}$ denotes the support of a probability distribution. Since $V_a \in W^*_a$ with probability one, all the sets in $\mathrm{supp} P_{W^*_a|V_a = v_a}$ contain $v_a$, hence all sets in $\mathrm{supp} P_{W^*|V = v_a}$ also contain $v_a$: $V \in W^*$ with probability one.

For all $a \in \mathcal{A}$ and $v_a \in \mathcal{V}_a$,
\begin{align}
    \lbrace \mathcal{S} \cap \mathcal{V}_a \:|\: \mathcal{S} \in \mathrm{supp} P_{W^*|V = v_a} \rbrace = \mathrm{supp} P_{W^*_a|V_a = v_a};
\end{align}
where $\mathrm{supp}$ denotes the support of a probability distribution.

\textit{Converse}
\begin{align}
    \!\!H_\kappa\left(\bigsqcup_{a \in \mathcal{A}}^{P_A} G_a \right) &  = \min_{V \in W \in \Gamma(G)} I(V,A;W) \\
    & \geq \min_{V \in W \in \Gamma(G)} \sum_{a \in \mathcal{A}} P_A(a) I(V;W|A = a) \\
    & = \sum_{a \in \mathcal{A}} P_A(a) \min_{V \in W \in \Gamma(G)} \! I(V;W|A = a) \\
    & = \sum_{a \in \mathcal{A}} P_A(a) \min_{V_a \in W \in \Gamma(G_a)} I(V_a;W) \\
    & = \sum_{a \in \mathcal{A}} P_A(a) H_\kappa(G_a); \end{align}
where \eqref{eq:proofHkappasplitA2} holds as $A$ is a deterministic function of $V$; \eqref{eq:proofHkappasplitA3} follows from the decomposition $I(V,A;W) = I(V;W|A) + I(A;W)$; and \eqref{eq:proofHkappasplitA5} holds as $V = V_A$.

Let $(\overline{a}_n)_{n \in \mathbb{N}^\star} \in \mathcal{A}^{\mathbb{N}^\star}$ be a sequence such that $T_{\overline{a}^n} \rightarrow P_A = \beta P'_A + (1-\beta)P''_A$ when $n \rightarrow \infty$.

Consider a sequence $(B_n)_{n \in \mathbb{N}^\star}$ of independent Bernoulli random variables such that for all $n \in \mathbb{N}^\star$,
\begin{align}
    \Pr(B_n = 0) = \frac{\beta P'_A(\overline{a}_n)}{P_A(\overline{a}_n)}.
\end{align}
By the strong law of large numbers,
\begin{align}
    \Pr\left(T_{B^n,\overline{a}^n} \underset{n \rightarrow \infty}{\rightarrow} (\beta P'_A, (1-\beta)P''_A) \right) = 1.
\end{align}
Therefore, there exists at least one realization $(b_n)_{n \in \mathbb{N}^\star}$ of $(B_n)_{n \in \mathbb{N}^\star}$ such that $T_{b^n,\overline{a}^n}$ converges to $\big(\beta P'_A, (1-\beta)P''_A \big)$. The convergences of marginal and conditional types yield
    \begin{align}
        & T_{b^n} \underset{n \rightarrow \infty}{\rightarrow} (\beta, 1-\beta),  \\
        & T_{a'^n} \underset{n \rightarrow \infty}{\rightarrow} P'_A, \qquad T_{a''^n} \underset{n \rightarrow \infty}{\rightarrow} P''_A,
    \end{align}
where $a' \doteq (\overline{a}_n)_{\substack{n\in \mathbb{N}^\star, \\ b_n = 0}}$ and $a'' \doteq (\overline{a}_n)_{\substack{n\in \mathbb{N}^\star, \\ b_n = 1}}$ are the extracted sequences.

Let $(\overline{a}_n)_{n \in \mathbb{N}^\star} \in \mathcal{A}^{\mathbb{N}^\star}$ be a sequence such that $T_{\overline{a}^n} \rightarrow P_A = \beta P'_A + (1-\beta)P''_A$ when $n \rightarrow \infty$.

Consider a sequence $(B_n)_{n \in \mathbb{N}^\star}$ of independent Bernoulli random variables such that for all $n \in \mathbb{N}^\star$,
\begin{align}
    \Pr(B_n = 0) = \frac{\beta P'_A(\overline{a}_n)}{P_A(\overline{a}_n)}.
\end{align}

By the strong law of large numbers,
\begin{align}
    \Pr\left(T_{B^n,\overline{a}^n} \underset{n \rightarrow \infty}{\rightarrow} (\beta P'_A, (1-\beta)P''_A) \right) = 1.
\end{align}

Therefore, there exists at least one realization $(b_n)_{n \in \mathbb{N}^\star}$ of $(B_n)_{n \in \mathbb{N}^\star}$ such that $T_{b^n,\overline{a}^n}$ converges to $\big(\beta P'_A, (1-\beta)P''_A \big)$. The convergences of marginal and conditional types yield
    \begin{align}
        & T_{b^n} \underset{n \rightarrow \infty}{\rightarrow} (\beta, 1-\beta),  \\
        & T_{a'^n} \underset{n \rightarrow \infty}{\rightarrow} P'_A, \qquad T_{a''^n} \underset{n \rightarrow \infty}{\rightarrow} P''_A,
    \end{align}
where $a' \doteq (\overline{a}_n)_{\substack{n\in \mathbb{N}^\star, \\ b_n = 0}}$ and $a'' \doteq (\overline{a}_n)_{\substack{n\in \mathbb{N}^\star, \\ b_n = 1}}$ are the extracted sequences.
